function sourcePattern(){const ctrls=I.controls.filter(c=>current.sourceControlIds.includes(c.id)&&c.kind==='action');const labels=[...new Set(ctrls.map(c=>cleanLabel(c.label)).filter(s=>s&&!/\{|· on|Pressable|Modal|Springy/.test(s)))].slice(0,35);return title('Existing destination',current.title,'This destination uses a shared screen pattern in this review.')+section('Existing options',actionList(labels.length?labels:['View route details']))+'<p class="section-copy">The complete original-control list remains in the review inspector.</p>';}
