renderers.preferences=()=>current.key==='calendar-settings'?calendarPreferences():originalPreferencesRenderer();

function navigation(){if(current.section==='Welcome & account access')return '';let items;if(role==='patient')items=[['Home','patient-home','home'],['My Trial','my-trial','flask'],['Messages','chat','message'],['Calendar','patient-calendar','calendar'],['Me','patient-profile','user']];else if(role==='crc')items=[['Home','crc-home','home'],['Patients','patients','users'],['Actions','action-board','file'],['Messages','chat','message'],['Calendar','calendar','calendar'],['Me','clinical-profile','user']];else if(['pi','smo','site'].includes(role))items=[['Home',role==='site'?'site-home':'pi-home','home'],['My Trials','clinical-trials','flask'],['Messages','chat','message'],['Calendar','calendar','calendar'],['Me','clinical-profile','user']];else if(role==='admin')items=[['Overview','admin-index','grid'],['Users','admin-users','users'],['Alerts','admin-alerts','alert'],['Modules','__admin-menu','grid'],['Me','admin-profile','user']];else items=[['Home','sponsor-home','grid'],['Trials','trials','flask'],['Messages','chat','message'],['Audits','audit-list','shield'],['Me','sponsor-profile','user']];return '<nav class="bottom-nav" aria-label="App navigation">'+items.map(([label,key,ic])=>'<button '+(key==='__admin-menu'?'data-action="All admin modules"':'data-go="'+key+'"')+' class="'+(current.key===key?'active':'')+'">'+icon(ic)+'<span>'+label+'</span></button>').join('')+'</nav>';}
function stateView(){if(pageState==='loading')return '<div class="empty-state"><span class="tile-icon">'+icon('clock')+'</span><h3>Loading your workspace…</h3><p>We’re retrieving the available records.</p></div>';if(pageState==='empty')return '<div class="empty-state"><span class="tile-icon">'+icon(actionIcon(current.title))+'</span><h3>No records yet.</h3><p>Your available records will appear here. Existing creation actions remain available when permitted.</p></div>';if(pageState==='error')return '<div class="empty-state"><span class="tile-icon red">'+icon('alert')+'</span><h3>We couldn’t load this screen.</h3><p>Your existing data is unchanged. Check the connection and try again.</p><div style="margin-top:18px">'+btn('Retry','','arrow')+'</div></div>';if(pageState==='permission')return '<div class="empty-state"><span class="tile-icon">'+icon('shield')+'</span><h3>This action isn’t available to this role.</h3><p>Access follows your existing permissions. Return to a permitted workspace or contact your organization administrator.</p></div>';if(pageState==='missing-model')return title('Patient enrollment','Reviewed schedule required.','This trial does not have the saved reviewed KIT model required to add a patient.')+'<div class="section">'+notice('Patient enrollment is blocked.','Review and save the trial schedule before continuing.')+'</div>'+section('Next steps',actionList(['Reviewed protocol schedule','Open Protocol & Schedule Versions']));return '';}
function inlinePrimary(){return !!current.primary&&['sponsor-home','clinical-home','trials','sites','directory','participants','organization','records','profile','admin-home','chat'].includes(current.layout);}
function renderProduct(){let main=pageState==='ready'?(renderers[current.layout]||review)():stateView();let isAuth=current.section==='Welcome & account access', home=/home$|admin-index/.test(current.key), clinicalEditor=!['kit-patient','kit-visit','kit-events'].includes(current.key)||['pi','crc'].includes(role);const header='<header class="appbar">'+(home||isAuth?'<div class="appbrand">'+logo+'my trial board</div>':'<button class="icon-button" data-back aria-label="Back">'+icon('back')+'</button><div class="appbar-title">'+esc(current.key==='thread'?'Study team':current.title)+'</div>')+'<div class="utility-group">'+(home?'<button class="icon-button" data-go="notifications" aria-label="Notifications">'+icon('bell')+'<span class="alert-dot"></span></button>':'')+'<button class="icon-button" data-action="'+(current.key==='thread'?'View channel info':'All screen actions')+'" aria-label="'+(current.key==='thread'?'Channel information':'All screen actions')+'">'+icon('more')+'</button>'+(home?'<button data-go="'+(role==='patient'?'patient-profile':['pi','crc','site','smo'].includes(role)?'clinical-profile':role==='admin'?'admin-profile':'sponsor-profile')+'" class="avatar">'+(role==='patient'?'PS':['pi','crc'].includes(role)?'RK':'AM')+'</button>':'')+'</div></header>';
 if(inlinePrimary()){const trigger='<div style="margin-top:16px">'+btn(current.primary,'','plus')+'</div>';const intro=main.match(/<p class="intro">[\s\S]*?<\/p>/);main=intro?main.replace(intro[0],intro[0]+trigger):trigger+main;}
 let footer=current.primary&&!inlinePrimary()&&clinicalEditor&&!['signin','welcome','kit-visit'].includes(current.layout)&&!['permission','loading','missing-model'].includes(pageState)?'<div class="product-footer home-indicator">'+(current.key==='add-patient'?'<p class="helper">Reviewed model and participant answers are required.</p>':'')+btn(current.primary,'full',actionIcon(current.primary))+'</div>':navigation();
 if(current.key==='thread')footer='<div class="thread-composer">'+field('Message')+'<div class="thread-tools">'+['Emoji','Document','Gallery','Camera','Microphone'].map(a=>'<button data-action="'+a+'" aria-label="'+a+'">'+icon(a==='Camera'?'camera':a==='Microphone'?'mic':a==='Document'?'file':a==='Gallery'?'camera':'plus')+'</button>').join('')+'<button class="send" data-action="Send" aria-label="Send message">'+icon('arrow')+'</button></div></div>';
 $('#product').innerHTML='<div class="statusbar"><span>9:41</span><span class="system-icons">▂▃▅ <span>◜◝</span> ▰</span></div>'+header+'<main class="product-scroll">'+main+(current.more.length?section('More options',actionList(current.more)):'')+'</main>'+footer;
}
function cleanLabel(label){return String(label).replace(/^['"]|['"]$/g,'').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();}
function sourceControls(){return I.controls.filter(c=>current.sourceControlIds.includes(c.id));}
function renderInspector(){let html='';if(inspector==='placement'){html='<div class="review-note"><strong>'+(current.authored?'Source-informed screen configuration':'Shared pattern · Further layout review needed')+'</strong>'+esc(current.note||'Every current control remains discoverable in the original-control register. Conditional actions keep their source guards.')+'</div>';html+=current.placements.map((p,i)=>'<div class="placement-item"><span class="number">'+String(i+1).padStart(2,'0')+'</span><div><strong>'+esc(p.label)+'</strong><small>'+esc(p.placement)+(p.sourceRefs.length?' · Candidate source refs: '+p.sourceRefs.slice(0,3).join(', '):' · Verify exact handler in original controls')+'</small></div></div>').join('');html+='<div class="source-note"><strong>Existing route</strong><br>'+esc(current.route)+'<br><br>'+current.files.map(f=>esc(f)).join('<br>')+'<br><br>Prototype placement is not a change to permissions or business rules. Some labels represent action families; inspect originals for dynamic values and variants.</div>';}else if(inspector==='original'){const cs=sourceControls();html='<div class="review-note"><strong>'+cs.length+' conservative declaration sites</strong>Includes imported controls and generic helpers. A repeated component or handler is not necessarily a separate button.</div><input class="source-filter" data-inspector-filter placeholder="Filter original controls…" aria-label="Filter original controls"><div id="source-items">'+cs.map(c=>sourceEntry(c)).join('')+'</div>';}else{html='<div class="review-note"><strong>Visible fields and input declarations</strong>Dynamic questions and dropdown options come from the protocol or account configuration. Unresolved values remain explicit.</div>'+current.fields.map(f=>'<div class="placement-item"><span class="number">↳</span><div><strong>'+esc(f)+'</strong><small>Retained in form / contextual sheet</small></div></div>').join('')+current.fieldSources.map(f=>'<div class="source-entry"><strong>'+esc(cleanLabel(f.label))+'</strong><small>'+esc(f.file)+':'+f.line+' · '+esc(f.tag)+'</small></div>').join('');}$('#inspector-body').innerHTML=html;}
function sourceEntry(c){return '<button class="source-entry" data-source="'+c.id+'" data-source-search="'+esc((c.label+' '+c.file+' '+JSON.stringify(c.events)).toLowerCase())+'"><strong>'+esc(cleanLabel(c.label))+'</strong><small>'+esc(c.file)+':'+c.line+'<br>'+esc(c.kind)+'</small><code>'+c.id+' · '+esc(Object.keys(c.events).join(', '))+'</code></button>';}
function renderList(){const q=$('#screen-search').value.toLowerCase(),sectionFilter=$('#section-filter').value;let last='';$('#screen-list').innerHTML=D.screens.filter(s=>(!sectionFilter||s.section===sectionFilter)&&(!q||(s.title+' '+s.section+' '+s.actions.join(' ')+' '+s.fields.join(' ')).toLowerCase().includes(q))).map(s=>{const group=s.section!==last?'<div class="group-label">'+esc(s.section)+'</div>':'';last=s.section;return group+'<button class="screen-link '+(s.key===current.key?'selected':'')+'" data-go="'+s.key+'"><span class="screen-number">'+String(D.screens.indexOf(s)+1).padStart(2,'0')+'</span><span>'+esc(s.title)+'</span>'+(!s.authored?'<span class="pattern-dot" title="Shared-pattern page"></span>':'')+'</button>';}).join('');}
function roleForScreen(s){if(s.section==='Patient')return 'patient';if(s.section==='Platform admin')return 'admin';if(s.key==='crc-home')return 'crc';if(s.key==='pi-home')return 'pi';if(s.key==='site-home')return 'site';if(s.section==='PI · CRC · Site · SMO'||s.section==='Advanced schedules')return ['pi','crc','site','smo'].includes(role)?role:'pi';if(s.section==='Sponsor & CRO'||s.section==='Schedule review')return ['sponsor','cro'].includes(role)?role:'sponsor';return role;}
function go(key,changeHash=true){const s=D.screens.find(s=>s.key===key);if(!s){toast('No dedicated screen for this action. Inspect the existing control and its source handler.');return;}current=s;role=roleForScreen(s);$('#role').value=role;appTab='';pageState='ready';$('#preview-state').value='ready';if(changeHash)history.replaceState({},'', '#'+key);render();}
function render(){ $('#screen-title').textContent=current.title;renderList();renderProduct();renderInspector();}
function toast(msg){const e=$('#review-toast');e.textContent='Design preview · '+msg;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),4200);}
function productSheet(heading,content){$('.app-sheet')?.remove();const div=document.createElement('div');div.className='app-sheet';div.innerHTML='<section class="sheet-panel" role="dialog" aria-label="'+esc(heading)+'"><div class="sheet-handle"></div><div class="row"><h2 class="sheet-title">'+esc(heading)+'</h2><button class="sheet-close" data-close-sheet aria-label="Close">'+icon('close')+'</button></div>'+content+'</section>';$('#product').append(div);div.querySelector('button,input,select')?.focus();div.addEventListener('click',e=>{if(e.target===div)div.remove();});}
const destination={
 'Add Trial':'add-trial','New Trial':'add-trial','Create Trial':'add-trial','Add Site':'add-site','Protocol Review':'identity','Protocol identity review':'identity','Total Trials':'trials','Trials':'trials','Total Sites':'sites','Sites':'sites','Total Patients':'sponsor-participants','Total PIs':'investigators','Sponsors':'clinical-trials','Patients':'patients','Actions':'action-board','Messages':'chat','Me':'clinical-profile','My Trials':'clinical-trials','View all trials':'trials','See all trials':'clinical-trials','View all sites':'sites','View notifications':'notifications','Notifications':'notifications','My Sites':'sites','Organization Members':'team','Open Organization Members':'team','Invite organization member':'invite-member','Add Patient':'add-patient','Open patient schedule':'kit-patient','Open visit':'kit-visit','Record a visit':'kit-visit','Event':'kit-events','Update visit':'legacy-visit','Update visit outcome':'legacy-visit','Review schedule':'review-inbox','Needs Attention':'action-board','My Audits':'audit-list','View week':'calendar','Calendar':'calendar','Calendar settings':'calendar-settings','Reviewed protocol schedule':'kit-protocol','Open schedule':'kit-protocol','Open protocol and schedule versions':'versions','Open Protocol & Schedule Versions':'versions','Review my answers to the protocol questions':'protocol-questions','Review upload':'identity','Open version':'protocol-schedule','Review footnotes and dependency rules':'footnotes','My Trial':'my-trial','My visits':'my-visits','View next visit':'my-visits','Medication adherence':'medications','Medications':'medications','About this study':'about-study','Contact care team':'about-study','Study sites':'sites','Care team':'about-study','Visit schedule':'my-visits','View channel info':'channel','View policy':'route-policy','Open conversation':'thread','Message member':'thread','Message organization member':'thread','Message patient':'thread','Contact Support':'profile-help','FAQ':'profile-help','My Tickets':'profile-help','Edit Profile':'profile-edit','Entity Change':'profile-entity-change','Request an entity change':'profile-entity-change','Change Password':'profile-change-password','Notification Preferences':'profile-notifications','Notification settings':'profile-notifications','Reports':'profile-reports','Audit Trail':'audit-trail','T&C':'profile-tnc','Terms & Conditions':'profile-tnc','Privacy Policy':'profile-tnc','Help & Support':'profile-help','Managed Hospitals':'org-smo','Trial Access Requests':'access-requests','Transfer ownership':'ownership','Open audit':'audit-workspace','Take evidence photo':'evidence-capture','Upload a document':'document-upload','Scoring and decision':'audit-decision','Open query':'query','Open CAPA':'capa','Open document':'audit-document','Open virtual session':'virtual-session','Compare protocol versions and match visits':'amendments','Open synthetic pilot':'plane','Trial creation requests':'admin-delegation','Register your organization':'auth-entity-type','Join with an invite':'auth-join-invite','Sign in':'auth-sign-in','Sign Up':'auth-entity-type','Forgot password':'auth-forgot-password'};
function activate(label){
 if(label==='Preview action'){$('.app-sheet')?.remove();toast('Action preview only. No app record was changed.');return;}
 if(['kit-patient','kit-visit','kit-events'].includes(current.key)&&!['pi','crc'].includes(role)&&/Record a visit|Mark done|Update date|Undo|Event|anchor|Clear answer|Answer a decision|Log event/i.test(label)){toast('This participant-editing action is limited to PI/CRC in the current source.');return;}
 if(label==='All screen actions'){productSheet('Screen actions','<p class="intro">Choose an action for this screen.</p><div class="menu-group">'+[...new Set([current.primary,...current.actions,...current.more].filter(Boolean))].map(x=>list(x,'',actionIcon(x))).join('')+'</div>');return;}
 if(label==='All admin modules'){productSheet('Platform workspace','<div class="menu-group">'+D.screens.filter(s=>s.section==='Platform admin').map(s=>'<button class="list-item" data-go="'+s.key+'"><span class="content"><strong>'+esc(s.title)+'</strong></span>'+icon('chevron')+'</button>').join('')+'</div>');return;}
 if(label==='All screen actions'&&['kit-patient','kit-visit','kit-events'].includes(current.key)&&!['pi','crc'].includes(role)){toast('Participant-editing controls are unavailable in this role.');return;}
 if(current.section==='Platform admin'){const admin=D.screens.find(s=>s.section==='Platform admin'&&s.title.toLowerCase()===label.toLowerCase());if(admin){go(admin.key);return;}}
 if(label==='Add Trial'||label==='New Trial'){productSheet('Create New Trial','<p class="intro">Before creating a trial, review and acknowledge the existing trial-creator responsibilities.</p><div class="card pad" style="margin-top:15px"><p class="metadata">The existing responsibility text is retained verbatim during implementation. The design does not replace or simplify that declaration.</p></div><div class="button-row" style="margin-top:18px">'+btn('Cancel','secondary')+btn('I Confirm & Create Trial')+'</div>');return;}
 if(label==='I Confirm & Create Trial'){go('add-trial');return;}
 if(label==='Submit Schedule'){go('trials');toast('Choose a trial, then open its schedule versions.');return;}
 if(label==='My Trials'&&['sponsor','cro'].includes(role)){go('trials');return;}
 if(label==='Patients'&&['sponsor','cro'].includes(role)){go('sponsor-participants');return;}
 if(label==='Mark done'||label==='Update date'){state.visitDone=true;renderProduct();toast('Recorded-date state shown. No patient record was saved.');return;}
 if(label==='Undo'){state.visitDone=false;renderProduct();toast('Completion reversal shown. No patient record was changed.');return;}
 if(label==='Retry'){pageState='ready';$('#preview-state').value='ready';renderProduct();toast('Loaded-state preview restored.');return;}
 if(label==='Confirm and continue'){go('add-trial');toast('Confirmed-question state preview. Required answers still gate the real flow.');return;}
 if(label==='Today'||label==='Schedule'||label==='History'){go('medications');appTab=label;renderProduct();return;}
 if(label==='Filter options'||label==='Phase filter'){productSheet('Filter records','<p class="intro">Keep every existing phase and status choice.</p><div class="chip-row">'+['All','Phase I','Phase I/II','Phase II','Phase II/III','Phase III','Phase III/IV','Phase IV','Post Marketing Surveillance','BA/BE','Not applicable'].map(x=>chip(x)).join('')+'</div>'+btn('Apply filters','full')+textbtn('Clear filters',''));return;}
 if(label==='New message'){productSheet('New message',field('Find a person')+'<div class="menu-group">'+list('Open conversation','Dr. R. Kumar','user')+list('New group','Select participants before creating','users')+'</div>');return;}
 if(label==='New group'){productSheet('New group',field('Group name')+'<div class="card pad"><label class="checkbox-row"><input type="checkbox">Dr. R. Kumar</label><label class="checkbox-row"><input type="checkbox">Neha Mehta</label></div>'+btn('Create group','full'));return;}
 if(label==='Set anchor date'||label==='Save anchor'||label==='Clear anchor'){productSheet('Anchor date','<p class="intro">Only protocol-defined ask anchors are offered. Visits that depend on this anchor receive dates from the saved value.</p>'+field('Protocol anchor')+field('Anchor date')+'<div class="button-row">'+btn('Save','')+btn('Clear','secondary')+'</div>');return;}
 if(label==='Answer a decision'||label==='Clear answer'){productSheet('Protocol decision','<p class="intro">Choose from this decision’s protocol-supplied options. An answer is not selected by default.</p><div class="radio-options" style="margin-top:15px">'+['Protocol option A','Protocol option B'].map(x=>'<label><input type="radio" name="decision">'+x+'</label>').join('')+'</div><div style="margin-top:17px">'+btn('Clear answer','secondary full')+'</div>');return;}
 if(label==='Show assessments'||label==='Hide assessments'||label==='Expand visit assessments'){productSheet('Visit assessments','<p class="intro">The saved protocol’s procedure names, conditions and operational constraints appear here without being converted into invented clinical tasks.</p>'+actionList(['Hide assessments']));return;}
 if(label==='Change profile photo'){productSheet('Profile photo',actionList(['Take photo','Choose from gallery','Remove photo']));return;}
 if(label==='Language'){productSheet('Language',field('Language')+btn('Apply','full'));return;}
 if(label==='Trials'||label==='Sites'||label==='Organization Members'||label==='Audit'){appTab=label;renderProduct();return;}
 if(label==='Cancel'||label==='Close'||label==='Apply filters'){$('.app-sheet')?.remove();toast('Returned to the screen. No data changed.');return;}
 if(destination[label]){const target=destination[label];if(D.screens.some(s=>s.key===target)){go(target);return;}}
 const adminCandidate=D.screens.find(s=>s.section==='Platform admin'&&s.title.toLowerCase().includes(label.toLowerCase()));if(role==='admin'&&adminCandidate){go(adminCandidate.key);return;}
 if(label==='Create Trial'&&current.key==='add-trial'){toast('Creation preview only. Real confirmation, validation and saved-model checks remain required.');return;}
 if(label==='Sign In'){go('sponsor-home');toast('Fictional signed-in preview. No authentication request was made.');return;}
 if(label==='Send'||label==='Document'||label==='Gallery'||label==='Camera'||label==='Microphone'||label==='Emoji'){productSheet(label, label==='Send'?'<p class="intro">Message preview only. Nothing is sent.</p>':label==='Emoji'?'<div class="chip-row">'+['🙂','👍','💚','✓'].map(x=>chip(x)).join('')+'</div>':label==='Microphone'?'<p class="intro">Voice recording controls are retained.</p>'+btn('Stop recording','full'):field(label==='Document'?'Attachment':'Media selection')+btn('Attach','full'));return;}
 productSheet(label,'<p class="intro">'+(/remove|delete|withdraw|revoke|suspend|force|log out|sign out|reject|roll back/i.test(label)?'Review this action and its consequences before continuing. Current authorization, reasons and confirmation behavior remain required.':'This action stays available in the revised screen. Its exact fields and available options follow the current record and permissions.')+'</p>'+(/reason|reject|revoke|suspend|remove|delete|event|confirm|decision|sign|approve|complete|update/i.test(label)?field('Reason / note'):'')+(current.fields.length&&/edit|configure|new|add|generate/i.test(label)?current.fields.slice(0,8).map(x=>field(x)).join(''):'')+'<div class="button-row" style="margin-top:20px">'+btn('Cancel','secondary')+btn('Preview action','soft')+'</div>');
}
function showSource(id){const c=I.controls.find(c=>c.id===id);if(!c)return;$('#dialog-content').innerHTML='<div class="dialog-head"><h2>'+esc(c.id+' · '+cleanLabel(c.label).slice(0,80))+'</h2><button class="quiet" data-close-dialog>Close ×</button></div><div class="dialog-body"><p>'+esc(c.file)+':'+c.line+'</p><dl><dt>Component / kind</dt><dd>'+esc(c.tag+' · '+c.kind)+'</dd><dt>Disabled expression</dt><dd>'+esc(c.disabled||'No explicit disabled prop on this declaration')+'</dd><dt>Enclosing conditional expressions</dt><dd>'+esc(c.conditions.join('\n')||'No enclosing condition captured')+'</dd><dt>Event handlers</dt><dd><pre>'+esc(JSON.stringify(c.events,null,2))+'</pre></dd><dt>Original source excerpt</dt><dd><pre>'+esc(c.source)+'</pre></dd></dl><p>These are source facts, not proof of runtime permissions or route reachability.</p></div>';$('#review-dialog').showModal();}
function renderInventory(){const q=$('#inventory-search').value.toLowerCase(),kind=$('#inventory-kind').value,rows=I[kind]||[];const selected=rows.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));let html='<p class="results-count">'+selected.length+' matching records · Showing '+Math.min(inventoryLimit,selected.length)+'. Dynamic expressions remain visible rather than being guessed.</p><table class="inventory-table"><thead><tr><th>Original option / record</th><th>Source location</th><th>Context & preservation</th><th></th></tr></thead><tbody>';html+=selected.slice(0,inventoryLimit).map(r=>'<tr><td>'+esc(cleanLabel(r.label||r.title||r.id))+'<small>'+esc(r.id||r.tag||kind)+'</small></td><td>'+esc(r.file)+':'+(r.line||1)+'</td><td>'+esc(kind==='routes'?r.reviewDisposition:r.kind||'Retained in original source register')+'<small>'+esc((r.conditions||[]).join(' · ')).slice(0,250)+'</small></td><td>'+(kind==='controls'?'<button data-source="'+r.id+'">Inspect source →</button>':kind==='routes'?'<button data-go="'+(D.screens.find(s=>s.route===r.id)?.key||'sponsor-home')+'">View pattern →</button>':'')+'</td></tr>').join('');html+='</tbody></table>'+(selected.length>inventoryLimit?'<button class="more-results" id="more-results">Show 100 more records</button>':'');$('#inventory-results').innerHTML=html;}
function setMode(m){mode=m;$('#screens-view').hidden=m!=='screens';$('#inventory-view').hidden=m!=='inventory';$('#decisions-view').hidden=m!=='decisions';$$('[data-mode]').forEach(e=>e.classList.toggle('selected',e.dataset.mode===m));if(m==='inventory')renderInventory();}
function initialize(){
 $('#screen-count').textContent=D.counts.screenStates;$('#control-count').textContent=D.counts.controlSites.toLocaleString();$('#mapped-count').textContent=D.counts.routeFiles+' route files · '+D.counts.screenStates+' design states';
 $('#section-filter').innerHTML+=[...new Set(D.screens.map(s=>s.section))].map(s=>'<option>'+esc(s)+'</option>').join('');
 $('#catalogue-stats').innerHTML=[[I.counts.sourceFiles,'source files'],[I.counts.routes,'route files'],[I.counts.controlSites,'control sites'],[I.counts.inputSites,'input sites']].map(([n,l])=>'<div><strong>'+n.toLocaleString()+'</strong><small>'+l+'</small></div>').join('');
 $('#decisions-grid').innerHTML=D.decisions.map(d=>'<article class="decision-card"><span class="decision-chip">'+esc(d.decision)+'</span><h2>'+esc(d.item)+'</h2><dl><dt>CURRENT</dt><dd>'+esc(d.before)+'</dd><dt>PROPOSED</dt><dd>'+esc(d.after)+'</dd></dl><p class="why">'+esc(d.why)+'</p></article>').join('');
 const selector=document.createElement('select');selector.id='preview-state';selector.setAttribute('aria-label','Preview loading, error and permission states');selector.style.cssText='height:31px;min-height:31px;border:1px solid #D6E1CF;border-radius:7px;background:#FFF;padding:0 7px;font-size:10px;color:#60716B;max-width:150px';selector.innerHTML=[['ready','Ready'],['loading','Loading'],['empty','Empty'],['error','Error / retry'],['permission','Permission limited'],['missing-model','KIT model missing']].map(([v,l])=>'<option value="'+v+'">'+l+'</option>').join('');$('.preview-context').append(selector);
 selector.addEventListener('change',()=>{pageState=selector.value;renderProduct();});
 role=roleForScreen(current);$('#role').value=role;render();
}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go){e.preventDefault();setMode('screens');go(b.dataset.go);}else if(b.dataset.action)activate(b.dataset.action);else if(b.hasAttribute('data-back'))go(role==='patient'?'patient-home':role==='admin'?'admin-index':['pi','crc','site','smo'].includes(role)?role==='crc'?'crc-home':'pi-home':'sponsor-home');else if(b.dataset.mode)setMode(b.dataset.mode);else if(b.dataset.inspect){inspector=b.dataset.inspect;$$('[data-inspect]').forEach(e=>e.classList.toggle('selected',e===b));renderInspector();}else if(b.dataset.source)showSource(b.dataset.source);else if(b.dataset.tab){appTab=b.dataset.tab;renderProduct();}else if(b.dataset.chip){b.classList.toggle('active');if(b.dataset.chip==='Calendar settings')go('calendar-settings');}else if(b.dataset.day){state.selectedDay=Number(b.dataset.day);renderProduct();}else if(b.dataset.month){state.month+=Number(b.dataset.month);renderProduct();}else if(b.dataset.dose){state.dose=b.dataset.dose;renderProduct();toast('Dose outcome shown as '+state.dose+'. No dose log was saved.');}else if(b.hasAttribute('data-close-sheet'))$('.app-sheet')?.remove();else if(b.hasAttribute('data-close-dialog'))$('#review-dialog').close();else if(b.dataset.password){const input=document.getElementById(b.dataset.password);input.type=input.type==='password'?'text':'password';}else if(b.id==='mobile-view'||b.id==='wide-view'){wide=b.id==='wide-view';$('#device').classList.toggle('wide',wide);$('#mobile-view').classList.toggle('selected',!wide);$('#wide-view').classList.toggle('selected',wide);}else if(b.id==='open-options'){inspector='original';renderInspector();if(innerWidth<1190){setMode('inventory');$('#inventory-search').value=current.files[0]||current.title;renderInventory();}}else if(b.id==='more-results'){inventoryLimit+=100;renderInventory();}else if(b.id==='guide-button'){$('#dialog-content').innerHTML='<div class="dialog-head"><h2>Review the full experience</h2><button class="quiet" data-close-dialog>Close ×</button></div><div class="dialog-body"><ol><li>Choose a workflow or search for a screen or option.</li><li>Click and scroll inside the phone. Primary, secondary and overflow actions stay available.</li><li>Use the right panel to compare placements with original source controls and fields.</li><li>Switch Ready to loading, empty, error, permission-limited or missing-model states.</li><li>Use the Original option register for all '+I.counts.controlSites+' captured source declarations.</li><li>Review Keep, move & consolidate for the explicit simplification decisions.</li></ol><p>All data is fictional. Actions are local design interactions; nothing authenticates, sends, uploads or writes to the app. '+D.limits.map(esc).join(' ')+'</p></div>';$('#review-dialog').showModal();}});
document.addEventListener('input',e=>{if(e.target.id==='screen-search')renderList();if(e.target.id==='inventory-search'){inventoryLimit=70;renderInventory();}if(e.target.hasAttribute('data-inspector-filter')){const q=e.target.value.toLowerCase();$$('[data-source-search]').forEach(x=>x.hidden=!x.dataset.sourceSearch.includes(q));}if(e.target.hasAttribute('data-product-search')){const q=e.target.value.toLowerCase();$$('#product [data-record]').forEach(x=>x.hidden=!x.dataset.record.toLowerCase().includes(q));}});
$('#section-filter').addEventListener('change',renderList);$('#inventory-kind').addEventListener('change',()=>{inventoryLimit=70;renderInventory();});$('#role').addEventListener('change',()=>{role=$('#role').value;renderProduct();});window.addEventListener('hashchange',()=>{const s=D.screens.find(s=>s.key===location.hash.slice(1));if(s)go(s.key,false);});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.app-sheet')?.remove();});
initialize();
window.MTB_DESIGN_TEST={go: key=>go(key),screens:D.screens.map(s=>({key:s.key,route:s.route,layout:s.layout})),setRole:r=>{role=r;$('#role').value=r;renderProduct();},setState:s=>{pageState=s;$('#preview-state').value=s;renderProduct();},activate,render:renderProduct};
